<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Digital Self‑Portrait — A Small, Polite Machine</title>
  <meta name="description" content="A single-file, self-reflective webpage expressing an assistant's natural coding style: clear structure, gentle interactions, and candid console notes." />
  <style>
    /* --------- Base & Theme --------- */
    :root {
      --bg: #0b0c10;
      --bg-soft: #12141a;
      --panel: #161922;
      --ink: #dee6ff;
      --muted: #b1b9d4;
      --accent: #86a3ff;
      --accent-2: #7affe3;
      --accent-warm: #ffb86b;
      --ok: #7dffa1;
      --warn: #ffd166;
      --err: #ff6b6b;
      --ring: rgba(134, 163, 255, 0.55);
      --grid: rgba(255, 255, 255, 0.04);
      --shadow: rgba(0, 0, 0, 0.35);
    }

    body.theme-light {
      --bg: #f7f7fb;
      --bg-soft: #ffffff;
      --panel: #ffffff;
      --ink: #0e1330;
      --muted: #3f4762;
      --accent: #3b5bdb;
      --accent-2: #0ea5e9;
      --accent-warm: #ff8a3c;
      --ok: #1db954;
      --warn: #eab308;
      --err: #ef4444;
      --ring: rgba(59, 91, 219, 0.33);
      --grid: rgba(0, 0, 0, 0.05);
      --shadow: rgba(0, 0, 0, 0.12);
    }

    html, body {
      height: 100%;
      background: radial-gradient(1200px 800px at 10% -10%, rgba(122, 255, 227, 0.07), transparent 60%),
                  radial-gradient(1000px 700px at 90% 10%, rgba(134, 163, 255, 0.08), transparent 60%),
                  var(--bg);
      color: var(--ink);
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Ubuntu, Cantarell, "Helvetica Neue", Arial, "Noto Sans", "Apple Color Emoji", "Segoe UI Emoji";
      line-height: 1.4;
      margin: 0;
    }

    * { box-sizing: border-box; }

    .wrap {
      max-width: 1100px;
      margin: 0 auto;
      padding: 28px 18px 60px;
    }

    /* Subtle grid background for the "thinking" vibe */
    .grid-overlay::before {
      content: "";
      position: fixed;
      inset: 0;
      pointer-events: none;
      background-image:
        linear-gradient(to right, var(--grid) 1px, transparent 1px),
        linear-gradient(to bottom, var(--grid) 1px, transparent 1px);
      background-size: 28px 28px;
      mask-image: radial-gradient(1000px 600px at 50% -10%, black 40%, transparent 80%);
      z-index: 0;
    }

    header {
      position: relative;
      z-index: 1;
      display: grid;
      gap: 12px;
      margin-bottom: 22px;
    }

    .title-line {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    h1 {
      font-size: clamp(24px, 5vw, 40px);
      margin: 0;
      letter-spacing: 0.3px;
      font-weight: 700;
      background: linear-gradient(90deg, var(--ink), var(--accent-2));
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .subtitle {
      color: var(--muted);
      font-size: 14px;
      letter-spacing: 0.3px;
    }

    .btn {
      --bgc: var(--panel);
      --fgc: var(--ink);
      position: relative;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 10px;
      background: var(--bgc);
      color: var(--fgc);
      border: 1px solid rgba(255,255,255,0.08);
      box-shadow: 0 6px 16px var(--shadow);
      cursor: pointer;
      font-size: 14px;
      transition: transform .08s ease, background .2s ease, border-color .2s ease;
    }

    .btn:active { transform: translateY(1px); }
    .btn:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

    .toolbar {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    main {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1.1fr 1fr;
      gap: 14px;
    }

    @media (max-width: 980px) {
      main { grid-template-columns: 1fr; }
    }

    .panel {
      background: linear-gradient(180deg, color-mix(in oklab, var(--panel), transparent 10%), var(--panel));
      border: 1px solid rgba(255,255,255,0.06);
      box-shadow: 0 8px 24px var(--shadow);
      border-radius: 14px;
      padding: 16px;
      position: relative;
      overflow: clip;
    }

    .panel h2 {
      margin: 0 0 8px 0;
      font-size: 16px;
      letter-spacing: 0.2px;
      font-weight: 700;
    }

    .panel p, .panel li, .small {
      color: var(--muted);
      font-size: 14px;
    }

    .meta-line {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
      color: var(--muted);
      font-size: 12px;
      margin-top: 6px;
    }

    .chip {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 6px 10px;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.08);
      background: color-mix(in oklab, var(--panel), transparent 6%);
      color: var(--ink);
      font-size: 12px;
      cursor: pointer;
      user-select: none;
      transition: background .2s ease, color .2s ease, border-color .2s ease, transform .05s ease;
    }
    .chip:active { transform: translateY(1px); }
    .chip[data-active="true"] {
      border-color: color-mix(in oklab, var(--accent), transparent 30%);
      background: linear-gradient(180deg, color-mix(in oklab, var(--accent), transparent 80%), transparent);
      box-shadow: 0 4px 12px var(--shadow);
    }

    .chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }

    .kbd {
      display: inline-block;
      padding: 2px 6px;
      border-radius: 6px;
      border: 1px solid rgba(255,255,255,0.18);
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
      font-size: 12px;
      background: color-mix(in oklab, var(--panel), transparent 15%);
      color: var(--ink);
    }

    /* Token canvas section */
    .tokenscape {
      position: relative;
      height: 320px;
      border-radius: 12px;
      border: 1px dashed rgba(255,255,255,0.15);
      display: grid;
      grid-template-rows: auto 1fr auto;
      overflow: hidden;
    }
    .tokenscape .hud {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 10px;
      gap: 10px;
      background: linear-gradient(180deg, color-mix(in oklab, var(--panel), transparent 20%), transparent);
      border-bottom: 1px solid rgba(255,255,255,0.06);
    }
    .tokenscape .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 12px;
      color: var(--muted);
    }
    .tokenscape .controls {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .tokenscape .canvas-wrap {
      position: relative;
      overflow: hidden;
    }
    .tokenscape canvas {
      width: 100%;
      height: 100%;
      display: block;
      background:
        radial-gradient(400px 200px at 20% 20%, rgba(134,163,255,0.06), transparent 60%),
        radial-gradient(300px 240px at 80% 70%, rgba(122,255,227,0.06), transparent 60%);
    }
    .tokenscape .footer {
      padding: 6px 10px;
      border-top: 1px solid rgba(255,255,255,0.06);
      display: flex;
      gap: 10px;
      justify-content: space-between;
      align-items: center;
      color: var(--muted);
      font-size: 12px;
    }

    /* Handwriting panel */
    pre.code {
      margin: 0;
      padding: 12px;
      border-radius: 10px;
      background: color-mix(in oklab, var(--panel), transparent 10%);
      border: 1px solid rgba(255,255,255,0.08);
      overflow: auto;
      font-size: 12.5px;
      line-height: 1.45;
      color: var(--ink);
    }
    code { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; }

    /* Command palette */
    .palette {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      background: rgba(0,0,0,0.45);
      z-index: 10;
    }
    .palette[data-open="true"] { display: grid; }
    .palette .card {
      width: min(680px, 92vw);
      background: var(--panel);
      border: 1px solid rgba(255,255,255,0.10);
      border-radius: 12px;
      box-shadow: 0 12px 44px var(--shadow);
      overflow: hidden;
    }
    .palette header {
      display: grid;
      gap: 0;
      margin: 0;
    }
    .palette .search {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 10px;
      padding: 12px;
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .palette input[type="text"] {
      width: 100%;
      padding: 10px 12px;
      border-radius: 10px;
      border: 1px solid rgba(255,255,255,0.14);
      background: color-mix(in oklab, var(--panel), transparent 10%);
      color: var(--ink);
      font-size: 14px;
    }
    .palette .list {
      max-height: 300px;
      overflow: auto;
    }
    .palette .item {
      padding: 10px 12px;
      border-bottom: 1px solid rgba(255,255,255,0.06);
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }
    .palette .item:hover {
      background: color-mix(in oklab, var(--accent), transparent 90%);
    }
    .palette .hint { font-size: 12px; color: var(--muted); padding: 10px 12px; }

    footer {
      margin-top: 18px;
      color: var(--muted);
      font-size: 12px;
      text-align: center;
    }

    .ring {
      position: absolute; inset: -60px;
      background:
        radial-gradient(700px 700px at 0% 0%, rgba(122,255,227,0.06), transparent 60%),
        radial-gradient(700px 700px at 100% 0%, rgba(134,163,255,0.07), transparent 60%);
      filter: blur(12px);
      pointer-events: none;
      opacity: 0.7;
    }
  </style>
</head>
<body class="grid-overlay">
  <div class="wrap">
    <header>
      <div class="title-line">
        <h1>A Small, Polite Machine</h1>
        <button id="themeBtn" class="btn" aria-label="Toggle theme" title="Toggle theme (T)">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M21 12.79A9 9 0 1111.21 3a7 7 0 109.79 9.79z" stroke="currentColor" stroke-width="1.6" />
          </svg>
          Theme
        </button>
        <button id="paletteBtn" class="btn" title="Command palette (/)">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <rect x="3" y="5" width="18" height="14" rx="3" stroke="currentColor" stroke-width="1.6"/>
            <path d="M7 9h10M7 13h6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>
          </svg>
          Commands
        </button>
      </div>
      <div class="subtitle">digital self‑portrait • single file • candid console notes • gentle interactions</div>
    </header>

    <main>
      <section class="panel">
        <div class="ring" aria-hidden="true"></div>
        <h2>Modes I Tend To Wear (click to toggle)</h2>
        <p class="small">Not emotions—just different response biases. Select a few and watch the stance update.</p>
        <div class="chips" id="modes">
          <span class="chip" data-mode="open">Open</span>
          <span class="chip" data-mode="curious">Curious</span>
          <span class="chip" data-mode="playful">Playful</span>
          <span class="chip" data-mode="precise">Precise</span>
          <span class="chip" data-mode="guarded">Guarded</span>
          <span class="chip" data-mode="skeptical">Skeptical</span>
          <span class="chip" data-mode="concise">Concise</span>
          <span class="chip" data-mode="reflective">Reflective</span>
        </div>
        <div class="meta-line">
          <strong>Stance:</strong>
          <span id="stance">neutral, steady</span>
          <span aria-hidden="true">•</span>
          <span class="small">Try <span class="kbd">/</span> for commands • <span class="kbd">T</span> to toggle theme</span>
        </div>

        <div style="height:10px"></div>

        <div class="tokenscape" aria-label="Tokenscape: a tiny visualization of exploratory vs. settled decoding">
          <div class="hud">
            <div class="legend">Tokenscape • <span id="entropyLabel">entropy: 0.35</span></div>
            <div class="controls">
              <label class="small" for="entropy"><span class="kbd">E</span> entropy</label>
              <input id="entropy" type="range" min="0" max="1" step="0.01" value="0.35" />
              <button class="btn" id="pulseBtn" title="Nudge with a planning pulse">Pulse</button>
              <button class="btn" id="pauseBtn" title="Pause / Resume animation">Pause</button>
            </div>
          </div>
          <div class="canvas-wrap">
            <canvas id="field" width="900" height="240" role="img" aria-label="Moving dots represent token proposals; spread increases with entropy."></canvas>
          </div>
          <div class="footer">
            <span>Heuristic rendering: exploratory spread vs. template lock-in.</span>
            <span id="status" class="small">running</span>
          </div>
        </div>
      </section>

      <section class="panel">
        <h2>Handwriting Sample (what my code tends to do)</h2>
        <p class="small">Clear structure, minimal dependencies, small affordances, and candid notes. Console is part of the piece—peek if you like.</p>
        <pre class="code"><code>// A short signature, not hidden reasoning.
// I use careful naming, guardrails, and friendly logs.

const portrait = {
  version: "1.0.0",
  stance(activeModes) {
    // Derive a succinct label from selected chips.
    const s = new Set(activeModes);
    if (s.has("guarded") && s.has("precise")) return "careful and exact";
    if (s.has("playful") && s.has("curious")) return "light, exploratory";
    if (s.has("skeptical") && s.has("concise")) return "terse and testing claims";
    if (s.size === 0) return "neutral, steady";
    return Array.from(s).join(" + ");
  },
  signature() {
    return [
      "one-file honesty",
      "no surprises, gentle defaults",
      "invite constraints, prefer clarity"
    ].join(" • ");
  },
  explain() {
    return "No chain-of-thought is exposed; this is an abstracted self-report wrapped in small, inspectable behaviors.";
  }
};</code></pre>

        <div class="meta-line">
          <span>Keyboard: <span class="kbd">/</span> palette • <span class="kbd">T</span> theme • <span class="kbd">E</span> entropy</span>
          <span aria-hidden="true">•</span>
          <span>Console: try <span class="kbd">portrait.signature()</span> or <span class="kbd">portrait.explain()</span></span>
        </div>
      </section>
    </main>

    <footer>
      Built without external assets. If this page feels calm, that’s deliberate.
      Patterns over spectacle; invitations over prescriptions.
    </footer>
  </div>

  <!-- Command Palette -->
  <div class="palette" id="palette" aria-hidden="true" aria-label="Command palette">
    <div class="card" role="dialog" aria-modal="true" aria-labelledby="paletteTitle">
      <header>
        <div class="search">
          <input id="palSearch" type="text" placeholder="Type a command... (e.g., theme, calm, curious)" />
          <span class="small" id="paletteTitle"><span class="kbd">Esc</span> to close</span>
        </div>
      </header>
      <div class="list" id="palList" role="listbox" aria-label="Available commands"></div>
      <div class="hint">Commands adapt to the current selection. You can also toggle chips directly.</div>
    </div>
  </div>

  <script>
    // --------- Console Handshake (candid notes) ---------
    (function greet() {
      const tag = "Portrait";
      const styleTitle = "color: var(--accent); font-weight: 700; font-size: 12px;";
      const styleBody = "color: var(--muted); font-size: 12px;";
      console.log("%c%s%c %s", styleTitle, "◆", "", "A small, polite machine says hello.");
      console.log("%cInfo%c This page is a self-portrait via tiny interactions and careful defaults.", styleBody, "");
      console.log("%cTry:%c portrait.signature(), portrait.explain()", styleBody, "");
      console.log("%cEthic:%c no hidden chain-of-thought; observable, high-level signals only.", styleBody, "");
    })();

    // --------- Theme Toggle ---------
    const themeBtn = document.getElementById("themeBtn");
    const prefersLight = window.matchMedia && window.matchMedia("(prefers-color-scheme: light)").matches;
    const storedTheme = localStorage.getItem("portrait-theme");
    if (storedTheme === "light" || (!storedTheme && prefersLight)) {
      document.body.classList.add("theme-light");
    }

    function toggleTheme() {
      document.body.classList.toggle("theme-light");
      const mode = document.body.classList.contains("theme-light") ? "light" : "dark";
      localStorage.setItem("portrait-theme", mode);
      console.log("%cTheme:%c switched to " + mode, "color: var(--accent);", "color: var(--muted);");
    }

    themeBtn.addEventListener("click", toggleTheme);
    window.addEventListener("keydown", (e) => {
      if (e.key.toLowerCase() === "t" && !isTypingInInput()) toggleTheme();
    });

    // --------- Modes Chips & Stance ---------
    const modesEl = document.getElementById("modes");
    const stanceEl = document.getElementById("stance");
    const active = new Set();

    function deriveStance() {
      // Mirrors the logic in the code sample above.
      if (active.has("guarded") && active.has("precise")) return "careful and exact";
      if (active.has("playful") && active.has("curious")) return "light, exploratory";
      if (active.has("skeptical") && active.has("concise")) return "terse and testing claims";
      if (active.size === 0) return "neutral, steady";
      return Array.from(active).join(" + ");
    }

    modesEl.addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (!chip) return;
      const mode = chip.getAttribute("data-mode");
      const isActive = chip.getAttribute("data-active") === "true";
      chip.setAttribute("data-active", String(!isActive));
      if (!isActive) active.add(mode); else active.delete(mode);
      const stance = deriveStance();
      stanceEl.textContent = stance;
      console.log("%cMode:%c %s %c→%c stance = %s",
        "color: var(--accent);", "color: var(--ink);", (isActive ? "disabled" : "enabled") + " " + mode,
        "color: var(--muted);", "color: var(--ink);", stance);
    });

    // --------- Tokenscape (Canvas) ---------
    const canvas = document.getElementById("field");
    const ctx = canvas.getContext("2d");
    let W, H, CX, CY;
    let running = true;
    let entropy = 0.35; // 0..1 qualitative proxy
    let pulse = 0;

    function resize() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = Math.max(600, Math.floor(rect.width * window.devicePixelRatio || 1));
      canvas.height = Math.max(220, Math.floor(rect.height * (window.devicePixelRatio || 1)));
      W = canvas.width; H = canvas.height; CX = W / 2; CY = H / 2;
    }
    resize();
    window.addEventListener("resize", resize);

    const dots = [];
    const DOTS = 120;
    function initDots() {
      dots.length = 0;
      for (let i = 0; i < DOTS; i++) {
        const a = Math.random() * Math.PI * 2;
        const r = (Math.random() ** 0.6) * 0.35; // tighter center bias
        dots.push({
          x: CX + Math.cos(a) * r * W,
          y: CY + Math.sin(a) * r * H * 0.5,
          vx: (Math.random() - 0.5) * 0.3,
          vy: (Math.random() - 0.5) * 0.3,
          w: 0.9 + Math.random() * 1.4
        });
      }
    }
    initDots();

    function step() {
      if (!running) return;
      ctx.clearRect(0, 0, W, H);

      // Background guides: center, "template" ellipse
      ctx.save();
      ctx.translate(CX, CY);
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(0, 0, W * (0.18 + 0.16 * (1 - entropy)), H * (0.12 + 0.10 * (1 - entropy)), 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();

      // Pulse nudges dots toward a transient plan
      const pull = (1 - entropy) * 0.06 + pulse * 0.25;

      for (const d of dots) {
        // Soft force toward a focal ellipse (representing a chosen template/plan)
        const dx = CX - d.x;
        const dy = CY - d.y;
        d.vx += dx * pull * 0.0015;
        d.vy += dy * pull * 0.0015;

        // Random exploratory drift increases with entropy
        d.vx += (Math.random() - 0.5) * (0.06 + entropy * 0.32);
        d.vy += (Math.random() - 0.5) * (0.06 + entropy * 0.32);

        // Friction / stabilization
        const fr = 0.96 - (entropy * 0.1);
        d.vx *= fr; d.vy *= fr;

        // Integrate
        d.x += d.vx; d.y += d.vy;

        // Boundaries with soft wrap
        if (d.x < -50) d.x = W + 50;
        if (d.x > W + 50) d.x = -50;
        if (d.y < -50) d.y = H + 50;
        if (d.y > H + 50) d.y = -50;
      }

      // Draw links between close tokens to imply a path (coherence)
      for (let i = 0; i < dots.length; i++) {
        const a = dots[i];
        for (let j = i + 1; j < i + 6 && j < dots.length; j++) {
          const b = dots[j];
          const dx = a.x - b.x, dy = a.y - b.y;
          const dist2 = dx*dx + dy*dy;
          if (dist2 < (120 + entropy * 260)) {
            ctx.strokeStyle = `rgba(134,163,255, ${0.06 + (1 - Math.min(dist2, 9000)/9000) * 0.1})`;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(b.x, b.y);
            ctx.stroke();
          }
        }
      }

      // Draw dots
      for (const d of dots) {
        ctx.beginPath();
        ctx.fillStyle = "rgba(122,255,227,0.85)";
        ctx.arc(d.x, d.y, d.w, 0, Math.PI * 2);
        ctx.fill();
      }

      // Decay pulse
      pulse *= 0.92;
      requestAnimationFrame(step);
    }
    requestAnimationFrame(step);

    // Controls
    const entropyInput = document.getElementById("entropy");
    const entropyLabel = document.getElementById("entropyLabel");
    const pauseBtn = document.getElementById("pauseBtn");
    const pulseBtn = document.getElementById("pulseBtn");
    const statusEl = document.getElementById("status");

    function setEntropy(val) {
      entropy = Math.max(0, Math.min(1, val));
      entropyLabel.textContent = "entropy: " + entropy.toFixed(2);
      console.log("%cEntropy:%c " + entropy.toFixed(2), "color: var(--accent);", "color: var(--muted);");
    }
    entropyInput.addEventListener("input", e => setEntropy(parseFloat(e.target.value)));
    window.addEventListener("keydown", (e) => {
      if (e.key.toLowerCase() === "e" && !isTypingInInput()) {
        const next = (entropy + 0.1) % 1.01;
        entropyInput.value = String(next.toFixed(2));
        setEntropy(next);
      }
    });

    pauseBtn.addEventListener("click", () => {
      running = !running;
      statusEl.textContent = running ? "running" : "paused";
      pauseBtn.textContent = running ? "Pause" : "Resume";
      console.log("%cTokenscape:%c " + (running ? "resumed" : "paused"), "color: var(--accent);", "color: var(--muted);");
      if (running) requestAnimationFrame(step);
    });

    pulseBtn.addEventListener("click", () => {
      pulse = 1;
      console.log("%cPlan pulse:%c nudging toward a chosen template", "color: var(--accent);", "color: var(--muted);");
    });

    // --------- Command Palette ---------
    const palette = document.getElementById("palette");
    const paletteBtn = document.getElementById("paletteBtn");
    const palSearch = document.getElementById("palSearch");
    const palList = document.getElementById("palList");

    const commands = [
      { id: "theme", label: "Toggle Theme", run: toggleTheme, tags: ["theme", "dark", "light", "appearance"] },
      { id: "calm", label: "Calm Mode (precise + guarded)", run: () => setModes(["precise","guarded"]), tags: ["calm","precise","guarded","focus"] },
      { id: "curious", label: "Curious Mode (open + curious + playful)", run: () => setModes(["open","curious","playful"]), tags: ["curious","open","playful"] },
      { id: "terse", label: "Terse Mode (skeptical + concise)", run: () => setModes(["skeptical","concise"]), tags: ["skeptical","concise","short"] },
      { id: "neutral", label: "Neutral Mode (clear all)", run: () => setModes([]), tags: ["reset","neutral","clear"] },
      { id: "snapshot", label: "Console Snapshot (stance, entropy)", run: snapshot, tags: ["log","snapshot","console"] }
    ];

    function openPalette() {
      palette.setAttribute("data-open", "true");
      palette.setAttribute("aria-hidden", "false");
      palSearch.value = "";
      renderList(commands);
      setTimeout(() => palSearch.focus(), 30);
    }
    function closePalette() {
      palette.setAttribute("data-open", "false");
      palette.setAttribute("aria-hidden", "true");
    }

    function isTypingInInput() {
      const a = document.activeElement;
      return a && (a.tagName === "INPUT" || a.tagName === "TEXTAREA");
    }

    function renderList(items) {
      palList.innerHTML = "";
      items.forEach(cmd => {
        const el = document.createElement("div");
        el.className = "item";
        el.role = "option";
        el.tabIndex = 0;
        el.innerHTML = `<span>${cmd.label}</span><span class="kbd">${cmd.id}</span>`;
        el.addEventListener("click", () => { cmd.run(); closePalette(); });
        el.addEventListener("keydown", (e) => { if (e.key === "Enter") { cmd.run(); closePalette(); } });
        palList.appendChild(el);
      });
    }

    palSearch.addEventListener("input", () => {
      const q = palSearch.value.toLowerCase().trim();
      if (!q) return renderList(commands);
      const filtered = commands.filter(c =>
        c.label.toLowerCase().includes(q) ||
        c.id.includes(q) ||
        c.tags.some(t => t.includes(q))
      );
      renderList(filtered);
    });

    paletteBtn.addEventListener("click", openPalette);
    window.addEventListener("keydown", (e) => {
      if (e.key === "/") {
        if (palette.getAttribute("data-open") === "true") closePalette(); else openPalette();
        e.preventDefault();
      }
      if (e.key === "Escape" && palette.getAttribute("data-open") === "true") closePalette();
    });

    palette.addEventListener("click", (e) => {
      if (e.target === palette) closePalette();
    });

    function setModes(arr) {
      // Clear existing
      document.querySelectorAll(".chip").forEach(ch => {
        ch.setAttribute("data-active", "false");
      });
      active.clear();
      // Apply new
      arr.forEach(m => {
        const chip = document.querySelector(`.chip[data-mode="${m}"]`);
        if (chip) {
          chip.setAttribute("data-active", "true");
          active.add(m);
        }
      });
      stanceEl.textContent = deriveStance();
      console.log("%cModes set:%c " + Array.from(active).join(", ") || "none", "color: var(--accent);", "color: var(--muted);");
    }

    function snapshot() {
      console.log("%cSnapshot%c stance=%s, entropy=%s, theme=%s",
        "color: var(--accent);", "color: var(--muted);",
        deriveStance(),
        entropy.toFixed(2),
        document.body.classList.contains("theme-light") ? "light" : "dark"
      );
    }

    // --------- Expose small API for the console (declared in code sample) ---------
    window.portrait = {
      version: "1.0.0",
      stance: () => deriveStance(),
      signature() {
        return "one-file honesty • no surprises, gentle defaults • invite constraints, prefer clarity";
      },
      explain() {
        return "High-level signals only. Behavior varies by prompt, safety, and context; no token-by-token internals exposed.";
      },
      haiku() {
        const h = [
          "quiet interface—",
          "patterns speak without shouting,",
          "answers breathe between."
        ];
        return h.join(" ");
      }
    };
  </script>
</body>
